import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import api from "@/lib/api";
import { Button } from "@/components/ui/button";
import {
  Truck,
  CheckCircle2,
  Package,
  ChefHat,
  Download,
  XCircle,
  Phone,
  MapPin,
  Clock3,
  Sparkles,
} from "lucide-react";

const STAGES = [
  {
    key: "placed",
    label: "Order Placed",
    icon: Package,
    desc: " Your order has been received."
  },
  {
    key: "confirmed",
    label: "Confirmed",
    icon: ChefHat,
    desc: "👨‍🍳 Bakery is preparing your order."
  },
  {
    key: "rider_assigned",
    label: "Rider Assigned",
    icon: Truck,
    desc: "Rider is on the way to pick up your order."
  },
  {
    key: "delivered",
    label: "Delivered",
    icon: CheckCircle2,
    desc: "Order Delivered Successfully 🎉"
  },
];

const formatDateTime = (value) => {
  if (!value) return "—";

  const date = new Date(value);

  return Number.isNaN(date.getTime())
    ? "—"
    : date.toLocaleString();
};

export default function OrderDetail() {
  const { id } = useParams();

  const [o, setO] = useState(null);

  useEffect(() => {
    let interval;

    const fetchOrder = async () => {
      try {
        const { data } = await api.get(`/orders/${id}`);
        setO(data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchOrder();

    interval = setInterval(fetchOrder, 5000);

    return () => clearInterval(interval);
  }, [id]);

  function Row({ label, value, green }) {
    return (
      <div className="flex justify-between text-sm">
        <span className="text-gray-600">{label}</span>

        <span
          className={`font-semibold ${green ? "text-green-600" : ""
            }`}
        >
          {value}
        </span>
      </div>
    );
  }

  function Info({ icon, title, value }) {
    return (
      <div className="flex gap-4">

        <div className="w-10 h-10 rounded-full bg-orange-100 flex items-center justify-center text-orange-600">

          {icon}

        </div>

        <div>

          <div className="text-xs text-gray-500">
            {title}
          </div>

          <div className="font-medium">
            {value}
          </div>

        </div>

      </div>
    );
  }

  if (!o)
    return (
      <div className="py-24 text-center">
        <div className="inline-block w-14 h-14 rounded-full border-4 border-orange-300 border-t-orange-600 animate-spin" />
        <p className="mt-5 text-gray-500">
          Loading your order...
        </p>
      </div>
    );

  const idx = STAGES.findIndex(
    (s) => s.key === o.status
  );

  const invoice = () => {
    const cancellationNote = o.cancellation_reason
      ? `<p><b>Cancellation Reason:</b> ${o.cancellation_reason}</p>`
      : "";

    const html = `
<html>

<head>

<title>Invoice ${o.order_no}</title>

<style>

body{
font-family:Arial;
padding:40px;
max-width:700px;
margin:auto;
}

h1{
color:#D97706;
}

table{
width:100%;
border-collapse:collapse;
}

td,
th{
padding:8px;
border-bottom:1px solid #eee;
text-align:left;
}

</style>

</head>

<body>

<h1>SLV Bakery</h1>

<p>

<b>Invoice:</b> ${o.order_no}<br/>

<b>Order Date:</b> ${formatDateTime(
      o.created_at
    )}<br/>

<b>Status:</b> ${o.status}<br/>

<b>Customer:</b> ${o.user_name}<br/>

<b>Phone:</b> ${o.phone}<br/>

<b>Address:</b> ${o.address}

</p>

${cancellationNote}

<table>

<thead>

<tr>

<th>Item</th>

<th>Qty</th>

<th>Price</th>

<th>Total</th>

</tr>

</thead>

<tbody>

${o.items
        .map(
          (i) => `
<tr>

<td>${i.name}</td>

<td>${i.quantity}</td>

<td>₹${i.price}</td>

<td>₹${(
              i.price * i.quantity
            ).toFixed(0)}</td>

</tr>
`
        )
        .join("")}

</tbody>

</table>

<br/>

<p>

Subtotal ₹${o.subtotal}<br/>

Platform ₹${o.platform_fee}<br/>

Delivery ₹${o.delivery_charge}<br/>

Packaging ₹${o.packaging}<br/>

Discount -₹${o.discount}<br/>

<b>Total ₹${o.total}</b>

</p>

</body>

</html>
`;

    const w = window.open("", "_blank");

    w.document.write(html);

    w.document.close();

    w.print();
  };
  return (
    <div className="relative overflow-hidden bg-gradient-to-br from-orange-50 via-white to-amber-50 min-h-screen">

      {/* Background Blur */}

      <div className="absolute -top-24 -left-20 w-80 h-80 rounded-full bg-orange-200 blur-[140px] opacity-25" />

      <div className="absolute bottom-0 right-0 w-72 h-72 rounded-full bg-yellow-200 blur-[120px] opacity-20" />

      <div className="relative max-w-5xl mx-auto px-4 py-10 animate-in fade-in duration-700">

        {/* Hero */}

        <div className="rounded-3xl bg-gradient-to-r from-orange-500 to-amber-500 text-white shadow-xl p-8 mb-6">

          <div className="flex flex-wrap justify-between gap-5 items-center">

            <div>

              <p className="uppercase tracking-[0.25em] text-xs opacity-80">
                Order Details
              </p>

              <h1 className="text-4xl font-bold mt-2">
                {o.order_no}
              </h1>

              <div className="flex items-center gap-2 mt-5">

                <Clock3 className="w-4 h-4" />

                <span className="text-sm">
                  {formatDateTime(o.created_at)}
                </span>

              </div>

            </div>

            <div className="text-right">
              <Button
                onClick={invoice}
                className="mt-5 rounded-full bg-white text-orange-600 hover:bg-orange-100"
              >
                <Download className="w-4 h-4 mr-2" />
                Download Invoice
              </Button>
            </div>
          </div>
        </div>
        {/* ======================= TRACKING CARD ======================= */}

        <div className="bg-white rounded-3xl shadow-xl border border-orange-100 overflow-hidden mb-6">

          {/* Header */}
          <div className="bg-gradient-to-r from-orange-500 to-amber-500 px-6 py-5 text-white">
            <h2 className="text-xl font-bold flex items-center gap-2">
              <Package className="w-6 h-6" />
              Live Order Tracking
            </h2>

            <p className="text-sm opacity-90 mt-1">
              Track every stage of your bakery order.
            </p>
          </div>

          <div className="p-8">

            {/* ================= CANCELLED ================= */}

            {o.status === "cancelled" ? (

              <div className="text-center">

                <div className="mx-auto w-24 h-24 rounded-full bg-red-100 flex items-center justify-center animate-pulse">

                  <XCircle className="w-14 h-14 text-red-600" />

                </div>

                <h2 className="mt-6 text-3xl font-bold text-red-600">
                  Order Cancelled
                </h2>

                <p className="mt-3 text-gray-500 max-w-md mx-auto leading-7">
                  Unfortunately this order has been cancelled.
                  We hope to serve you again soon.
                </p>

                {o.cancellation_reason && (

                  <div className="mt-6 inline-flex rounded-2xl bg-red-50 px-5 py-3 text-red-700 font-medium border border-red-200">

                    Reason : {o.cancellation_reason}

                  </div>

                )}

              </div>

            ) : (

              <>

                {/* ================= TIMELINE ================= */}

                <div className="grid grid-cols-4 relative">

                  {STAGES.map((stage, i) => {

                    const Icon = stage.icon;

                    const active = i <= idx;

                    const current = i === idx;

                    return (

                      <div
                        key={stage.key}
                        className="relative flex flex-col items-center"
                      >

                        {/* Connecting Line */}

                        {i !== STAGES.length - 1 && (

                          <div
                            className={`absolute top-6 left-1/2 w-full h-1 rounded-full transition-all duration-700

                    ${i < idx
                                ? "bg-orange-500"
                                : "bg-gray-200"
                              }
                    
                    `}
                          />

                        )}

                        {/* Circle */}

                        <div

                          className={`

                  relative z-10

                  w-14

                  h-14

                  rounded-full

                  flex

                  items-center

                  justify-center

                  transition-all

                  duration-500

                  shadow-lg

                  ${active
                              ? "bg-gradient-to-br from-orange-500 to-amber-500 text-white"
                              : "bg-white border-2 border-gray-300 text-gray-400"
                            }

                  ${current
                              ? "animate-pulse scale-110"
                              : ""
                            }

                  `}
                        >
                          <Icon className="w-6 h-6" />
                        </div>
                        {/* Label */}
                        <div className="mt-4 text-center">
                          <div
                            className={`text-sm font-semibold
                    ${active
                                ? "text-orange-600"
                                : "text-gray-500"
                              }
                    `}
                          >
                            {stage.label}
                          </div>
                          {stage.desc && current && (
                            <div className="text-xs text-gray-500 mt-1">
                              {stage.desc}
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}

                </div>
                {/* ================= RIDER CARD ================= */}
                {(o.rider_name || o.rider_phone) && (
                  <div className=" rounded-2xl border border-orange-100 bg-gradient-to-r from-orange-50 to-white p-2 shadow">
                    <div className="flex items-center ">
                      <Truck className="w-7 h-7 text-orange-500" />
                      <h3 className="text-xl font-bold">
                        Delivery Partner
                      </h3>
                    </div>
                    <div className="grid md:grid-cols-2 gap-4">
                      {o.rider_name && (
                        <div className="rounded-xl bg-white border p-4">
                          <div className="text-xs text-gray-500">
                            Rider Name : <span className="font-semibold mt-1">{o.rider_name}</span>
                          </div>
                        </div>
                      )}
                      {o.rider_phone && (
                        <div className="rounded-xl bg-white border p-4">
                          <div className="text-xs text-gray-500 flex items-center gap-2">
                            <Phone className="w-4 h-4" />
                            Contact : <span className="font-semibold mt-1">{o.rider_phone}</span>
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                )}

              </>

            )}

          </div>

        </div>
        {/* ======================= ORDER DETAILS ======================= */}

        <div className="grid lg:grid-cols-[1.2fr_0.8fr] gap-6">

          {/* ITEMS */}

          <div className="bg-white rounded-3xl shadow-xl border border-orange-100 overflow-hidden">

            <div className="bg-gradient-to-r from-orange-500 to-amber-500 px-6 py-4 text-white">

              <h2 className="text-xl font-bold flex items-center gap-2">
                <Package className="w-6 h-6" />
                Ordered Items
              </h2>

            </div>

            <div className="p-6 space-y-4">

              {o.items.map((item, index) => (

                <div
                  key={index}
                  className="rounded-2xl border border-orange-100 bg-orange-50 hover:bg-orange-100 transition-all duration-300 p-5 flex justify-between items-center"
                >

                  <div>

                    <div className="font-semibold text-lg">
                      {item.name}
                    </div>

                    <div className="text-sm text-gray-500 mt-1">
                      Quantity : {item.quantity}
                    </div>

                  </div>

                  <div className="text-right">

                    <div className="font-bold text-orange-600 text-xl">
                      ₹{(item.price * item.quantity).toFixed(0)}
                    </div>

                    <div className="text-xs text-gray-500">
                      ₹{item.price} each
                    </div>

                  </div>

                </div>

              ))}

            </div>

          </div>

          {/* SUMMARY */}

          <div className="space-y-6">

            <div className="bg-white rounded-3xl shadow-xl border border-orange-100 overflow-hidden">

              <div className="bg-gradient-to-r from-orange-500 to-amber-500 px-6 py-4 text-white">

                <h2 className="text-xl font-bold">
                  Payment Summary
                </h2>

              </div>

              <div className="p-6 space-y-4">
                <Row
                  label="Subtotal"
                  value={`₹${o.subtotal}`}
                />
                <Row
                  label="Platform Fee"
                  value={`₹${o.platform_fee}`}
                />
                <Row
                  label="Delivery"
                  value={`₹${o.delivery_charge}`}
                />
                <Row
                  label="Packaging"
                  value={`₹${o.packaging}`}
                />
                {o.discount > 0 && (
                  <Row
                    label="Discount"
                    value={`- ₹${o.discount}`}
                    green
                  />
                )}
                <div className="border-t pt-5 flex justify-between items-center">
                  <span className="text-xl font-bold">
                    Grand Total
                  </span>
                  <span className="text-3xl font-bold text-orange-600 animate-pulse">
                    ₹{o.total}
                  </span>
                </div>
              </div>
            </div>
            {/* DELIVERY */}
            <div className="bg-white rounded-3xl shadow-xl border border-orange-100 p-6">
              <h3 className="font-bold text-xl mb-5">
                Delivery Information
              </h3>
              <div className="space-y-4">
                <Info
                  icon={<Clock3 className="w-5 h-5" />}
                  title="Ordered"
                  value={formatDateTime(o.created_at)}
                />
                {o.status === "delivered" && o.delivered_at && (
                  <Info
                    icon={<CheckCircle2 className="w-5 h-5 text-green-600" />}
                    title="Delivered"
                    value={formatDateTime(o.delivered_at)}
                  />
                )}
                <Info
                  icon={<MapPin className="w-5 h-5" />}
                  title="Delivery Address"
                  value={o.address}
                />
                <Info
                  icon={<Phone className="w-5 h-5" />}
                  title="Phone"
                  value={o.phone}
                />
                <Info
                  icon={<Package className="w-5 h-5" />}
                  title="Payment"
                  value={o.payment_method}
                />
              </div>
            </div>
          </div>
        </div>
        <div className="mt-10 text-center">
          <Link
            to="/my-orders"
            className="inline-flex items-center px-8 py-3 rounded-full bg-gradient-to-r from-orange-500 to-amber-500 text-white font-semibold hover:scale-105 transition-all duration-300 shadow-lg"
          >← Back to My Orders
          </Link>
        </div>
      </div>
    </div>
  );
}
